<div class="ai-panel-fragment"><h2>⚖️ Compare Products</h2><p>Choose two products to compare.</p><form action="{{ route('compare-products') }}" method="GET" data-ai-hub-form><select name="product_one" class="form-select mb-2"><option value="">First product</option>@foreach($products as $product)<option value="{{ $product->id }}" {{ optional($firstProduct)->id === $product->id ? 'selected' : '' }}>{{ $product->name }}</option>@endforeach</select><select name="product_two" class="form-select mb-2"><option value="">Second product</option>@foreach($products as $product)<option value="{{ $product->id }}" {{ optional($secondProduct)->id === $product->id ? 'selected' : '' }}>{{ $product->name }}</option>@endforeach</select><button class="btn btn-primary btn-sm w-100">Compare</button></form>@if($firstProduct && $secondProduct)<div class="ai-quick-compare"><b>{{ $firstProduct->name }}</b><span>₹{{ number_format((float) $firstProduct->price, 2) }} · ★ {{ $firstProduct->rating ?? 0 }}</span><b>{{ $secondProduct->name }}</b><span>₹{{ number_format((float) $secondProduct->price, 2) }} · ★ {{ $secondProduct->rating ?? 0 }}</span></div>@endif</div>
